export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdResults = Object.entries(thresholds).map(([metricId, min]) => {
    const metric = evaluations.find(m => m.id === metricId);
    const score = metric?.score;
    const passed = score !== null && score !== undefined && score >= min;
    return {
      metric: metricId,
      min,
      score,
      passed
    };
  });

  const allThresholdsPassed = thresholdResults.length === 0 || thresholdResults.every(t => t.passed);

  return {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations,
    ...(Object.keys(thresholds).length > 0 && {
      passed: allThresholdsPassed,
      thresholds: thresholdResults
    })
  };
}

