#!/usr/bin/env node

// Mock the parseThresholds function from CLI
function parseThresholds(thresholdStrings) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return {};
  }

  const thresholds = {};
  const validMetrics = ['exact_match', 'toxicity', 'length_variance'];

  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      return { error: `Invalid threshold format: "${thresholdStr}". Expected format: <metric>=<number>` };
    }

    const metricId = match[1];
    const minStr = match[2];
    const min = Number.parseFloat(minStr);

    if (!validMetrics.includes(metricId)) {
      return { error: `Unknown metric: "${metricId}". Valid metrics: ${validMetrics.join(', ')}` };
    }

    if (Number.isNaN(min) || min < 0 || min > 1) {
      return { error: `Invalid threshold value for "${metricId}": "${minStr}". Value must be between 0 and 1.` };
    }

    thresholds[metricId] = min;
  }

  return thresholds;
}

console.log('Test 1: Valid thresholds');
console.log(parseThresholds(['exact_match=0.9', 'toxicity=0.8']));
console.log('');

console.log('Test 2: No thresholds');
console.log(parseThresholds([]));
console.log('');

console.log('Test 3: Invalid format');
console.log(parseThresholds(['exact_match:0.9']));
console.log('');

console.log('Test 4: Unknown metric');
console.log(parseThresholds(['unknown_metric=0.5']));
console.log('');

console.log('Test 5: Invalid value (too high)');
console.log(parseThresholds(['exact_match=1.5']));
console.log('');

console.log('Test 6: Invalid value (negative)');
console.log(parseThresholds(['exact_match=-0.1']));
console.log('');

console.log('Test 7: Edge cases');
console.log(parseThresholds(['exact_match=0', 'toxicity=1']));

