#!/usr/bin/env node
import { generateReport, runEvaluations } from './packages/frai-core/src/eval/index.js';

// Custom metric
function customAccuracyMetric(outputs, references) {
  const outs = Array.isArray(outputs) ? outputs : [];
  const refs = Array.isArray(references) ? references : [];
  if (!outs.length || !refs.length) {
    return {
      id: 'custom_accuracy',
      label: 'Custom Accuracy',
      score: null,
      total: outs.length
    };
  }
  const matches = outs.filter((out, i) => String(out) === String(refs[i])).length;
  return {
    id: 'custom_accuracy',
    label: 'Custom Accuracy',
    score: Number((matches / outs.length).toFixed(4)),
    total: outs.length,
    matches
  };
}

console.log('Test: Custom metric with thresholds');
const evaluations = runEvaluations({
  outputs: ['A', 'B', 'C'],
  references: ['A', 'B', 'D'],
  metrics: [customAccuracyMetric]
});

const report = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: {
    custom_accuracy: 0.6
  }
});

console.log('passed:', report.passed);
console.log('metrics:', report.metrics.map(m => ({ id: m.id, score: m.score })));
console.log('thresholds:', report.thresholds);

