/**
 * Test that the CLI threshold implementation would work correctly
 * by simulating the parseThresholds and exit logic
 */

// Simulate CLI threshold parsing and exit code logic
function simulateCliRun(thresholdStrings, report) {
  const validMetrics = ['exact_match', 'toxicity', 'length_variance'];

  if (!thresholdStrings || thresholdStrings.length === 0) {
    console.log('  No thresholds, exit code: 0');
    return 0;
  }

  const thresholds = {};
  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      console.log(`  Error: Invalid format "${thresholdStr}", exit code: 2`);
      return 2;
    }

    const metricId = match[1];
    const min = Number.parseFloat(match[2]);

    if (!validMetrics.includes(metricId)) {
      console.log(`  Error: Unknown metric "${metricId}", exit code: 2`);
      return 2;
    }

    if (Number.isNaN(min) || min < 0 || min > 1) {
      console.log(`  Error: Invalid value "${min}" for "${metricId}", exit code: 2`);
      return 2;
    }

    thresholds[metricId] = min;
  }

  if (report.passed === false) {
    console.log('  Thresholds failed, exit code: 1');
    return 1;
