477	function parseThresholds(thresholdStrings?: string[]): Record<string, number> | null {
478	  if (!thresholdStrings || thresholdStrings.length === 0) {
479	    return {};
480	  }
481	
482	  const thresholds: Record<string, number> = {};
483	  const validMetrics = ['exact_match', 'toxicity', 'length_variance'];
484	
485	  for (const thresholdStr of thresholdStrings) {
486	    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
487	    if (!match) {
488	      log.error(`Invalid threshold format: "${thresholdStr}". Expected format: <metric>=<number>`);
489	      return null;
490	    }
491	
492	    const metricId = match[1];
493	    const minStr = match[2];
494	    const min = Number.parseFloat(minStr);
495	
496	    if (!validMetrics.includes(metricId)) {
497	      log.error(`Unknown metric: "${metricId}". Valid metrics: ${validMetrics.join(', ')}`);
498	      return null;
499	    }
500	
501	    if (Number.isNaN(min) || min < 0 || min > 1) {
502	      log.error(`Invalid threshold value for "${metricId}": "${minStr}". Value must be between 0 and 1.`);
503	      return null;
504	    }
505	
506	    thresholds[metricId] = min;
507	  }
508	
509	  return thresholds;
510	}
