561	function runFinetuneTemplateCommand(options: FinetuneTemplateOptions) {
562	  const template = Finetune.createGovernanceTemplate();
563	  const target = options.output ? path.resolve(options.output) : path.resolve(process.cwd(), 'frai-finetune-plan.json');
564	  fs.writeFileSync(target, JSON.stringify(template, null, 2), 'utf8');
565	  log.success('Fine-tuning governance template written.', { path: target });
566	}
