568	function runFinetuneValidateCommand(planPath: string, options: FinetuneValidateOptions) {
569	  const absolute = path.resolve(planPath);
570	  assertFileExists(absolute);
571	  const raw = fs.readFileSync(absolute, 'utf8');
572	  let parsed: unknown;
573	  try {
574	    parsed = JSON.parse(raw);
575	  } catch (error) {
576	    throw new Error(`Invalid JSON: ${(error as Error).message}`);
577	  }
578	  const validation = Finetune.validateGovernancePlan(parsed);
579	  if (!validation.valid) {
580	    log.error('Fine-tuning governance plan is invalid.');
581	    validation.errors.forEach((errorItem) => {
582	      console.error(` - ${errorItem.path}: ${errorItem.message}`);
583	    });
584	  } else {
585	    log.success('Fine-tuning governance plan is valid.');
586	  }
587	
588	  if (options.readiness) {
589	    const readiness = Finetune.calculateReadiness(parsed as Parameters<typeof Finetune.calculateReadiness>[0]);
590	    log.info('Readiness checkpoint status', readiness);
591	    console.log(Finetune.summarizeGovernance(parsed as Parameters<typeof Finetune.calculateReadiness>[0]));
592	  }
593	}
