616	    !options.scan &&
617	    !options.ci &&
618	    !options.setup &&
619	    !options.listDocs &&
620	    !options.clean &&
621	    !options.update &&
622	    !options.showConfig &&
623	    !options.key;
624	  if (exportOnly) {
